// Made by release/build.sh from the .fs files beside it. Do not edit; edit the .fs files and build again.
// It lets Mothlight No.01 open from an unzipped folder, where a browser will not fetch files.
self.MOTHLIGHT_ISF = {
"mothlight-solo.fs": "/*{\n    \"ISFVSN\": \"2\",\n    \"DESCRIPTION\": \"Mothlight.Solo: two video oscillators, the second bending the first, in a shape window, with optional colour by brightness; every pixel changes at most 3 times a second.\",\n    \"CREDIT\": \"NXLX.Systems and contributors\",\n    \"CATEGORIES\": [\n        \"Generator\",\n        \"Performance\"\n    ],\n    \"COST\": \"low: two waves, one arc tangent, one square root and a cosine colour a pixel\",\n    \"INPUTS\": [\n        {\n            \"NAME\": \"rate\",\n            \"LABEL\": \"Speed\",\n            \"TYPE\": \"float\",\n            \"MIN\": 0.02,\n            \"MAX\": 3.0,\n            \"DEFAULT\": 0.12\n        },\n        {\n            \"NAME\": \"bands\",\n            \"LABEL\": \"Bands\",\n            \"TYPE\": \"float\",\n            \"MIN\": 1.0,\n            \"MAX\": 24.0,\n            \"DEFAULT\": 4.0\n        },\n        {\n            \"NAME\": \"angle\",\n            \"LABEL\": \"Angle\",\n            \"TYPE\": \"float\",\n            \"MIN\": 0.0,\n            \"MAX\": 1.0,\n            \"DEFAULT\": 0.12\n        },\n        {\n            \"NAME\": \"bend\",\n            \"LABEL\": \"Bend\",\n            \"TYPE\": \"float\",\n            \"MIN\": 0.0,\n            \"MAX\": 0.6,\n            \"DEFAULT\": 0.3\n        },\n        {\n            \"NAME\": \"form\",\n            \"LABEL\": \"Pattern\",\n            \"TYPE\": \"long\",\n            \"VALUES\": [0, 1, 2, 3],\n            \"LABELS\": [\"Lines\", \"Rings\", \"Rays\", \"Spiral\"],\n            \"DEFAULT\": 1\n        },\n        {\n            \"NAME\": \"wave\",\n            \"LABEL\": \"Wave\",\n            \"TYPE\": \"long\",\n            \"VALUES\": [0, 1, 2, 3],\n            \"LABELS\": [\"Sine\", \"Triangle\", \"Saw\", \"Square\"],\n            \"DEFAULT\": 0\n        },\n        {\n            \"NAME\": \"shape\",\n            \"LABEL\": \"Window\",\n            \"TYPE\": \"long\",\n            \"VALUES\": [0, 1, 2, 3],\n            \"LABELS\": [\"Off\", \"Circle\", \"Square\", \"Diamond\"],\n            \"DEFAULT\": 0\n        },\n        {\n            \"NAME\": \"spread\",\n            \"LABEL\": \"Colour\",\n            \"TYPE\": \"float\",\n            \"MIN\": 0.0,\n            \"MAX\": 1.0,\n            \"DEFAULT\": 0.45\n        }\n    ]\n}*/\n// SPDX-FileCopyrightText: 2026 NXLX.Systems and contributors\n// SPDX-License-Identifier: Apache-2.0\n// An original shader written for Mothlight No.01 and nxlx.mastercontrol.\n\n// Flash safety: Osc A moves at 0.6 of the rate and Osc B at 0.2, and the bend is at most 0.6, so a pixel of A\n// changes at most 0.6 + 0.6 * pi * 0.2 = 0.98 times the rate (B's sine moves at most pi * 0.2 * rate a second,\n// and the bend scales that): under 3 a second with the rate capped at 3.\n// The slow drift of the angle turns the stripes too, and a turn moves them most past the pixels far from the centre\n// (up to 1.02 from it). With many bands at top speed the drift alone swept stripes past those about 3.5 times a\n// second, so its size is held to half of what the rate leaves of the 3. At usual speeds it is not changed.\n\nfloat wavef(float x, int k) {\n    float f = fract(x);\n    if (k == 0) {\n        return 0.5 + 0.5 * sin(x * 6.2831853);\n    }\n    if (k == 1) {\n        return 1.0 - abs(f * 2.0 - 1.0);\n    }\n    if (k == 2) {\n        return f;\n    }\n    return smoothstep(0.47, 0.53, f) - smoothstep(0.97, 1.0, f);\n}\n\nvoid main() {\n    vec2 uv = isf_FragNormCoord;\n    float hz = min(rate, 3.0);\n    float pa = fract(TIME * hz * 0.6);\n    float pb = fract(TIME * hz * 0.2);\n    // stripes swept past the farthest pixel for each radian of turn (A, and B through the bend when B is lines too),\n    // and the drift's fastest turn at full size, 0.04 * 2 pi * 2 pi * 0.03 * hz = 0.0474 * hz radians a second\n    float perRad = 1.02 * (bands + (form == 0 ? 0.6 * 3.14159265 * (bands * 0.66 + 1.0) : 0.0));\n    float natural = perRad * 0.0474 * hz;\n    float driftSize = 0.04 * min(1.0, 0.5 * max(0.0, 3.0 - 0.98 * hz) / max(natural, 0.0001));\n    float drift = sin(fract(TIME * hz * 0.03) * 6.2831853) * driftSize;\n\n    vec2 p = (uv - 0.5) * vec2(RENDERSIZE.x / RENDERSIZE.y, 1.0);\n    float r = length(p);\n    float th = atan(p.y, p.x) / 6.2831853;\n    float turn = (angle + drift) * 6.2831853;\n\n    // Osc B, the modulator: always a sine, so its bend is smooth\n    float bfreq = bands * 0.66 + 1.0;\n    float bx = 0.0;\n    if (form == 0) {\n        bx = dot(p, vec2(-sin(turn), cos(turn))) * bfreq;\n    }\n    if (form == 1) {\n        bx = r * bfreq;\n    }\n    if (form == 2) {\n        bx = th * floor(bfreq);\n    }\n    if (form == 3) {\n        bx = r * bfreq + th * floor(bfreq * 0.5 + 1.0);\n    }\n    float b = 0.5 + 0.5 * sin((bx - pb) * 6.2831853);\n\n    // Osc A, bent by B\n    float a = wavef(dot(p, vec2(cos(turn), sin(turn))) * bands + pa + (b - 0.5) * bend, wave);\n\n    // Shape window: 1 inside\n    float d = r;\n    if (shape == 2) {\n        d = max(abs(p.x), abs(p.y));\n    }\n    if (shape == 3) {\n        d = abs(p.x) + abs(p.y);\n    }\n    float m = 1.0;\n    if (shape > 0) {\n        m = 1.0 - smoothstep(0.27, 0.31, d);\n    }\n    float v = mix(b * 0.35, a, m);\n\n    // Colour by brightness; black stays black, and no colour at all is plain grey for a later stage to colour\n    vec3 pal = 0.5 + 0.5 * cos(6.2831853 * (v * spread + 0.62 + vec3(0.0, 0.33, 0.67)));\n    pal = mix(vec3(1.0), pal, clamp(spread * 4.0, 0.0, 1.0));\n    gl_FragColor = vec4(pal * pow(clamp(v, 0.0, 1.0), 0.7), 1.0);\n}\n",
"mothlight-duo.fs": "/*{\n  \"DESCRIPTION\": \"Mothlight.Duo: two matching video oscillators, a mixer with bend, and a shape window, in brightness only. Trails come from Mothlight.Trails and colour from Mothlight.Colour. Mothlight No.01.\",\n  \"CREDIT\": \"NXLX.Systems and contributors\",\n  \"ISFVSN\": \"2\",\n  \"CATEGORIES\": [\"Generator\", \"NXLX\"],\n  \"INPUTS\": [\n    {\"NAME\": \"a_wave\",  \"LABEL\": \"Wave\",      \"TYPE\": \"long\", \"VALUES\": [0,1,2,3], \"LABELS\": [\"Sine\",\"Triangle\",\"Saw\",\"Square\"], \"DEFAULT\": 0},\n    {\"NAME\": \"a_form\",  \"LABEL\": \"Pattern\",      \"TYPE\": \"long\", \"VALUES\": [0,1,2,3], \"LABELS\": [\"Lines\",\"Rings\",\"Rays\",\"Spiral\"], \"DEFAULT\": 0},\n    {\"NAME\": \"a_freq\",  \"LABEL\": \"Bands\",     \"TYPE\": \"float\", \"MIN\": 0.5, \"MAX\": 32.0, \"DEFAULT\": 3.0},\n    {\"NAME\": \"a_rate\",  \"LABEL\": \"Speed\",     \"TYPE\": \"float\", \"MIN\": -1.0, \"MAX\": 1.0, \"DEFAULT\": 0.08},\n    {\"NAME\": \"a_angle\", \"LABEL\": \"Angle\",     \"TYPE\": \"float\", \"MIN\": 0.0, \"MAX\": 1.0, \"DEFAULT\": 0.12},\n\n    {\"NAME\": \"b_wave\",  \"LABEL\": \"Wave\",      \"TYPE\": \"long\", \"VALUES\": [0,1,2,3], \"LABELS\": [\"Sine\",\"Triangle\",\"Saw\",\"Square\"], \"DEFAULT\": 0},\n    {\"NAME\": \"b_form\",  \"LABEL\": \"Pattern\",      \"TYPE\": \"long\", \"VALUES\": [0,1,2,3], \"LABELS\": [\"Lines\",\"Rings\",\"Rays\",\"Spiral\"], \"DEFAULT\": 1},\n    {\"NAME\": \"b_freq\",  \"LABEL\": \"Bands\",     \"TYPE\": \"float\", \"MIN\": 0.5, \"MAX\": 32.0, \"DEFAULT\": 2.0},\n    {\"NAME\": \"b_rate\",  \"LABEL\": \"Speed\",     \"TYPE\": \"float\", \"MIN\": -1.0, \"MAX\": 1.0, \"DEFAULT\": -0.05},\n    {\"NAME\": \"b_angle\", \"LABEL\": \"Angle\",     \"TYPE\": \"float\", \"MIN\": 0.0, \"MAX\": 1.0, \"DEFAULT\": 0.37},\n\n    {\"NAME\": \"mix_mode\", \"LABEL\": \"Mode\",     \"TYPE\": \"long\", \"VALUES\": [0,1,2,3], \"LABELS\": [\"Blend\",\"Add\",\"Multiply\",\"Difference\"], \"DEFAULT\": 0},\n    {\"NAME\": \"mix_amt\",  \"LABEL\": \"Balance\",   \"TYPE\": \"float\", \"MIN\": 0.0, \"MAX\": 1.0, \"DEFAULT\": 0.5},\n    {\"NAME\": \"a_fm\",     \"LABEL\": \"Bend\",     \"TYPE\": \"float\", \"MIN\": 0.0, \"MAX\": 1.0, \"DEFAULT\": 0.25},\n\n    {\"NAME\": \"shape_kind\", \"LABEL\": \"Window\", \"TYPE\": \"long\", \"VALUES\": [0,1,2,3], \"LABELS\": [\"Off\",\"Circle\",\"Square\",\"Diamond\"], \"DEFAULT\": 0},\n    {\"NAME\": \"shape_size\", \"LABEL\": \"Window size\",   \"TYPE\": \"float\", \"MIN\": 0.0, \"MAX\": 1.0, \"DEFAULT\": 0.6},\n    {\"NAME\": \"shape_soft\", \"LABEL\": \"Window softness\",   \"TYPE\": \"float\", \"MIN\": 0.0, \"MAX\": 1.0, \"DEFAULT\": 0.1}\n  ]\n}*/\n// SPDX-FileCopyrightText: 2026 NXLX.Systems and contributors\n// SPDX-License-Identifier: Apache-2.0\n// An original shader written for Mothlight No.01 and nxlx.mastercontrol.\n\n// Flash safety: oscillator speeds are capped at 1 cycle a second and the bend at 1, so a pixel of a square wave\n// changes at most 3 times a second.\n\n// Phase-continuous clocks. The NXLX runner adds each speed up every frame and sets nx_on = 1, so moving a speed\n// fader never jumps the picture. Other ISF hosts leave these at 0 and fall back to TIME * speed.\nuniform float nx_on;\nuniform float nx_pa;\nuniform float nx_pb;\n\nconst float TAU = 6.2831853;\n\nfloat wave(float x, int k) {\n\tfloat f = fract(x);\n\tif (k == 0) return 0.5 + 0.5 * sin(x * TAU);\n\tif (k == 1) return 1.0 - abs(f * 2.0 - 1.0);\n\tif (k == 2) return f;\n\treturn smoothstep(0.48, 0.52, f) - smoothstep(0.98, 1.0, f);\n}\n\n// where a pixel sits along an oscillator: both oscillators work the same way\nfloat along(int form, vec2 p, float r, float th, float freq, float angle) {\n\tif (form == 1) return r * freq;\n\tif (form == 2) return th * ceil(freq);\n\tif (form == 3) return r * freq + th * ceil(freq * 0.5);\n\treturn dot(p, vec2(cos(angle * TAU), sin(angle * TAU))) * freq;\n}\n\nvoid main() {\n\tvec2 uv = isf_FragNormCoord.xy;\n\tbool own = nx_on > 0.5;\n\tfloat pa = own ? nx_pa : TIME * a_rate;\n\tfloat pb = own ? nx_pb : TIME * b_rate;\n\n\tvec2 p = (uv - 0.5) * vec2(RENDERSIZE.x / RENDERSIZE.y, 1.0);\n\tfloat r = length(p);\n\tfloat th = atan(p.y, p.x) / TAU;\n\n\t// Rays and Spiral are turned by the angle too, so Angle does something on all but Rings\n\tfloat b = wave(along(b_form, p, r, th + b_angle, b_freq, b_angle) - pb, b_wave);\n\tfloat a = wave(along(a_form, p, r, th + a_angle, a_freq, a_angle) - pa + (b - 0.5) * a_fm, a_wave);\n\n\tfloat v;\n\tif (mix_mode == 0)      v = mix(a, b, mix_amt);\n\telse if (mix_mode == 1) v = min(1.0, a * (1.0 - mix_amt) * 2.0 + b * mix_amt * 2.0);\n\telse if (mix_mode == 2) v = sqrt(mix(a, a * b, mix_amt));\n\telse                    v = abs(a - b * mix_amt);\n\n\t// Window: 1 inside, and it masks the finished mix\n\tif (shape_kind > 0) {\n\t\tfloat d = shape_kind == 1 ? r : shape_kind == 2 ? max(abs(p.x), abs(p.y)) : abs(p.x) + abs(p.y);\n\t\tfloat edge = 0.01 + shape_soft * 0.3;\n\t\tv *= 1.0 - smoothstep(shape_size * 0.7 - edge, shape_size * 0.7 + edge, d);\n\t}\n\tgl_FragColor = vec4(vec3(v), 1.0);\n}\n",
"mothlight-trails.fs": "/*{\n    \"ISFVSN\": \"2\",\n    \"DESCRIPTION\": \"Mothlight.Trails, a feedback processor: the last picture is zoomed, turned and slid, then keyed under the playing one as trails.\",\n    \"CREDIT\": \"NXLX.Systems and contributors\",\n    \"CATEGORIES\": [\n        \"Filter\",\n        \"Feedback\"\n    ],\n    \"COST\": \"medium: six texture reads and one hue turn a pixel in the first pass, one read in the second, plus up to three history reads for Echo and Smear\",\n    \"INPUTS\": [\n        {\n            \"NAME\": \"inputImage\",\n            \"TYPE\": \"image\"\n        },\n        {\n            \"NAME\": \"feed\",\n            \"LABEL\": \"Length\",\n            \"TYPE\": \"float\",\n            \"MIN\": 0.0,\n            \"MAX\": 1.0,\n            \"DEFAULT\": 0.93\n        },\n        {\n            \"NAME\": \"key\",\n            \"LABEL\": \"Key\",\n            \"TYPE\": \"float\",\n            \"MIN\": 0.0,\n            \"MAX\": 1.0,\n            \"DEFAULT\": 0.3\n        },\n        {\n            \"NAME\": \"keyinto\",\n            \"LABEL\": \"Key into\",\n            \"TYPE\": \"long\",\n            \"VALUES\": [0, 1],\n            \"LABELS\": [\"Darks\", \"Lights\"],\n            \"DEFAULT\": 0\n        },\n        {\n            \"NAME\": \"zoom\",\n            \"LABEL\": \"Zoom\",\n            \"TYPE\": \"float\",\n            \"MIN\": -0.06,\n            \"MAX\": 0.06,\n            \"DEFAULT\": 0.008\n        },\n        {\n            \"NAME\": \"turn\",\n            \"LABEL\": \"Turn\",\n            \"TYPE\": \"float\",\n            \"MIN\": -0.02,\n            \"MAX\": 0.02,\n            \"DEFAULT\": 0.001\n        },\n        {\n            \"NAME\": \"shiftx\",\n            \"LABEL\": \"Slide across\",\n            \"TYPE\": \"float\",\n            \"MIN\": -0.02,\n            \"MAX\": 0.02,\n            \"DEFAULT\": 0.0\n        },\n        {\n            \"NAME\": \"shifty\",\n            \"LABEL\": \"Slide up\",\n            \"TYPE\": \"float\",\n            \"MIN\": -0.02,\n            \"MAX\": 0.02,\n            \"DEFAULT\": 0.0\n        },\n        {\n            \"NAME\": \"delaystyle\",\n            \"LABEL\": \"Delay\",\n            \"TYPE\": \"long\",\n            \"VALUES\": [0, 1],\n            \"LABELS\": [\"Echo\", \"Smear\"],\n            \"DEFAULT\": 0\n        },\n        {\n            \"NAME\": \"echotime\",\n            \"LABEL\": \"Time\",\n            \"TYPE\": \"float\",\n            \"MIN\": 0.05,\n            \"MAX\": 1.5,\n            \"DEFAULT\": 0.5\n        },\n        {\n            \"NAME\": \"repeats\",\n            \"LABEL\": \"Repeats\",\n            \"TYPE\": \"long\",\n            \"VALUES\": [1, 2, 3],\n            \"LABELS\": [\"1\", \"2\", \"3\"],\n            \"DEFAULT\": 2\n        },\n        {\n            \"NAME\": \"echo\",\n            \"LABEL\": \"Amount\",\n            \"TYPE\": \"float\",\n            \"MIN\": 0.0,\n            \"MAX\": 1.0,\n            \"DEFAULT\": 0.0\n        },\n        {\n            \"NAME\": \"edges\",\n            \"LABEL\": \"Edges\",\n            \"TYPE\": \"long\",\n            \"VALUES\": [0, 1, 2],\n            \"LABELS\": [\"Hold\", \"Wrap\", \"Reflect\"],\n            \"DEFAULT\": 2\n        },\n        {\n            \"NAME\": \"mirror\",\n            \"LABEL\": \"Mirror\",\n            \"TYPE\": \"long\",\n            \"VALUES\": [0, 1, 2, 3],\n            \"LABELS\": [\"Off\", \"Left/right\", \"Up/down\", \"Both\"],\n            \"DEFAULT\": 0\n        },\n        {\n            \"NAME\": \"hueturn\",\n            \"LABEL\": \"Hue drift\",\n            \"TYPE\": \"float\",\n            \"MIN\": -0.02,\n            \"MAX\": 0.02,\n            \"DEFAULT\": 0.0\n        },\n        {\n            \"NAME\": \"sharpen\",\n            \"LABEL\": \"Sharpen\",\n            \"TYPE\": \"float\",\n            \"MIN\": 0.0,\n            \"MAX\": 1.0,\n            \"DEFAULT\": 0.0\n        }\n    ],\n    \"PASSES\": [\n        {\n            \"TARGET\": \"drift\",\n            \"PERSISTENT\": true\n        },\n        {}\n    ]\n}*/\n// SPDX-FileCopyrightText: 2026 NXLX.Systems and contributors\n// SPDX-License-Identifier: Apache-2.0\n// An original shader written for Mothlight No.01 and nxlx.mastercontrol.\n\n// The first pass draws the drift buffer: the last picture, moved, with the playing picture keyed over it. The second\n// pass shows it. The NXLX web runner defines NXLX_HISTORY and adds pastA to pastC, pictures from a few seconds of\n// history, for Echo and Smear. Other ISF hosts (Mastercontrol's node included) skip that code, and Amount does nothing.\n// Nothing here inverts brightness or hue: in a loop that would flip every frame.\n\nvec2 edge(vec2 q) {\n    if (edges == 1) {\n        return fract(q);\n    }\n    if (edges == 2) {\n        return 1.0 - abs(1.0 - mod(q, 2.0));\n    }\n    return clamp(q, 0.0, 1.0);\n}\n\nvec3 hueDrift(vec3 c) {\n    // turn the hue around the grey axis\n    float a = hueturn * 6.2831853;\n    vec3 k = vec3(0.57735);\n    float cs = cos(a);\n    return clamp(c * cs + cross(k, c) * sin(a) + k * dot(k, c) * (1.0 - cs), 0.0, 1.0);\n}\n\nvoid main() {\n    vec2 uv = isf_FragNormCoord;\n    if (PASSINDEX == 1) {\n        vec3 cur = IMG_NORM_PIXEL(drift, uv).rgb;\n#ifdef NXLX_HISTORY\n        if (delaystyle == 0 && echo > 0.0) {\n            // Echo: copies of the picture from Time, twice Time and three times Time ago, each fainter, laid over the picture\n            vec3 ghost = IMG_NORM_PIXEL(pastA, uv).rgb * echo;\n            if (repeats >= 2) {\n                ghost = max(ghost, IMG_NORM_PIXEL(pastB, uv).rgb * echo * 0.6);\n            }\n            if (repeats >= 3) {\n                ghost = max(ghost, IMG_NORM_PIXEL(pastC, uv).rgb * echo * 0.36);\n            }\n            cur = max(cur, ghost);   // lighten: each copy keeps its shape instead of washing the picture out\n        }\n#endif\n        gl_FragColor = vec4(cur, 1.0);\n        return;\n    }\n    // folding here, in the first pass, mirrors the playing picture and the trails together, and the loop stays symmetric\n    if (mirror == 1 || mirror == 3) {\n        uv.x = 0.5 - abs(uv.x - 0.5);\n    }\n    if (mirror == 2 || mirror == 3) {\n        uv.y = 0.5 - abs(uv.y - 0.5);\n    }\n    float aspect = RENDERSIZE.x / RENDERSIZE.y;\n    vec2 q = (uv - 0.5) * vec2(aspect, 1.0) * (1.0 - zoom);\n    float a = turn * 6.2831853;\n    q = vec2(cos(a) * q.x - sin(a) * q.y, sin(a) * q.x + cos(a) * q.y);\n    q = q / vec2(aspect, 1.0) + 0.5 - vec2(shiftx, shifty);\n    q = edge(q);\n\n    vec3 back = IMG_NORM_PIXEL(drift, q).rgb;\n#ifdef NXLX_HISTORY\n    if (delaystyle == 1 && echo > 0.0) {\n        // Smear: frames from a third of Time, two thirds and all of Time ago, blended into the trails like a long exposure\n        vec3 old = (IMG_NORM_PIXEL(pastA, q).rgb + IMG_NORM_PIXEL(pastB, q).rgb + IMG_NORM_PIXEL(pastC, q).rgb) / 3.0;\n        back = mix(back, max(back, old), echo);\n    }\n#endif\n    vec2 px = 1.0 / RENDERSIZE;\n    vec3 around = IMG_NORM_PIXEL(drift, edge(q + vec2(px.x, 0.0))).rgb + IMG_NORM_PIXEL(drift, edge(q - vec2(px.x, 0.0))).rgb\n                + IMG_NORM_PIXEL(drift, edge(q + vec2(0.0, px.y))).rgb + IMG_NORM_PIXEL(drift, edge(q - vec2(0.0, px.y))).rgb;\n    back = clamp(back + (back * 4.0 - around) * sharpen * 0.5, 0.0, 1.0);\n    // at full Trails the picture holds; below that the last step takes faint 8-bit ghosts all the way to black\n    back = hueDrift(back) * feed;\n    if (feed < 0.999) {\n        back = max(back - 0.004, 0.0);\n    }\n\n    vec3 now = IMG_NORM_PIXEL(inputImage, uv).rgb;\n    float luma = dot(now, vec3(0.299, 0.587, 0.114));\n    float shows = smoothstep(key - 0.06, key + 0.06, luma);\n    if (keyinto == 1) {\n        shows = 1.0 - smoothstep(1.0 - key - 0.06, 1.0 - key + 0.06, luma);\n    }\n    gl_FragColor = vec4(mix(back, now, shows), 1.0);\n}\n",
"mothlight-colour.fs": "/*{\n    \"ISFVSN\": \"2\",\n    \"DESCRIPTION\": \"Mothlight.Colour, the last stage: colours the picture by brightness, sets its brightness and contrast, and can send out plain mono or a hard matte for masking.\",\n    \"CREDIT\": \"NXLX.Systems and contributors\",\n    \"CATEGORIES\": [\n        \"Filter\",\n        \"Color\"\n    ],\n    \"COST\": \"low: one texture read and one colour map a pixel\",\n    \"INPUTS\": [\n        {\n            \"NAME\": \"inputImage\",\n            \"TYPE\": \"image\"\n        },\n        {\n            \"NAME\": \"palette\",\n            \"LABEL\": \"Palette\",\n            \"TYPE\": \"long\",\n            \"VALUES\": [0, 1, 2, 3],\n            \"LABELS\": [\"Original\", \"Spectrum\", \"Two tone\", \"Heat\"],\n            \"DEFAULT\": 1\n        },\n        {\n            \"NAME\": \"hue\",\n            \"LABEL\": \"Hue\",\n            \"TYPE\": \"float\",\n            \"MIN\": 0.0,\n            \"MAX\": 1.0,\n            \"DEFAULT\": 0.55\n        },\n        {\n            \"NAME\": \"spread\",\n            \"LABEL\": \"Range\",\n            \"TYPE\": \"float\",\n            \"MIN\": 0.0,\n            \"MAX\": 1.5,\n            \"DEFAULT\": 0.7\n        },\n        {\n            \"NAME\": \"sat\",\n            \"LABEL\": \"Saturation\",\n            \"TYPE\": \"float\",\n            \"MIN\": 0.0,\n            \"MAX\": 1.5,\n            \"DEFAULT\": 1.0\n        },\n        {\n            \"NAME\": \"bright\",\n            \"LABEL\": \"Brightness\",\n            \"TYPE\": \"float\",\n            \"MIN\": 0.0,\n            \"MAX\": 2.0,\n            \"DEFAULT\": 1.1\n        },\n        {\n            \"NAME\": \"contrast\",\n            \"LABEL\": \"Contrast\",\n            \"TYPE\": \"float\",\n            \"MIN\": 0.0,\n            \"MAX\": 3.0,\n            \"DEFAULT\": 1.25\n        },\n        {\n            \"NAME\": \"mode\",\n            \"LABEL\": \"Output mode\",\n            \"TYPE\": \"long\",\n            \"VALUES\": [0, 1, 2],\n            \"LABELS\": [\"Colour\", \"Mono\", \"Matte\"],\n            \"DEFAULT\": 0\n        },\n        {\n            \"NAME\": \"invert\",\n            \"LABEL\": \"Invert\",\n            \"TYPE\": \"long\",\n            \"VALUES\": [0, 1],\n            \"LABELS\": [\"Off\", \"On\"],\n            \"DEFAULT\": 0\n        },\n        {\n            \"NAME\": \"matte\",\n            \"LABEL\": \"Matte level\",\n            \"TYPE\": \"float\",\n            \"MIN\": 0.0,\n            \"MAX\": 1.0,\n            \"DEFAULT\": 0.5\n        },\n        {\n            \"NAME\": \"soft\",\n            \"LABEL\": \"Matte softness\",\n            \"TYPE\": \"float\",\n            \"MIN\": 0.0,\n            \"MAX\": 0.5,\n            \"DEFAULT\": 0.04\n        }\n    ]\n}*/\n// SPDX-FileCopyrightText: 2026 NXLX.Systems and contributors\n// SPDX-License-Identifier: Apache-2.0\n// An original shader written for Mothlight No.01 and nxlx.mastercontrol.\n\n// Everything before this stage works in brightness, so this is the only place colour is decided. It runs after the\n// feedback loop, so nothing here can flip from frame to frame.\n\nconst float TAU = 6.2831853;\n\n// a fully bright colour at any hue, so a palette never dims the picture\nvec3 wheel(float h) {\n    vec3 c = 0.5 + 0.5 * cos(TAU * (h + vec3(0.0, 0.33, 0.67)));\n    return c / max(c.r, max(c.g, c.b));\n}\n\nvec3 hueTurn(vec3 c, float a) {\n    float cs = cos(a * TAU);\n    float sn = sin(a * TAU);\n    vec3 k = vec3(0.57735);\n    return c * cs + cross(k, c) * sn + k * dot(k, c) * (1.0 - cs);\n}\n\nvoid main() {\n    vec3 c = IMG_THIS_NORM_PIXEL(inputImage).rgb;\n    c = clamp((c - 0.5) * contrast + 0.5, 0.0, 1.0);\n    float x = dot(c, vec3(0.299, 0.587, 0.114));\n\n    vec3 col = hueTurn(c, hue);\n    if (palette == 1) {\n        col = wheel(x * spread + hue) * sqrt(x);\n    }\n    if (palette == 2) {\n        col = mix(wheel(hue), wheel(hue + spread * 0.5), x) * smoothstep(0.0, 0.2, x);\n    }\n    if (palette == 3) {\n        col = hueTurn(clamp(vec3(x * 3.0, x * 3.0 - 1.0, x * 3.0 - 2.0), 0.0, 1.0), hue - 0.55);\n    }\n    float grey = dot(col, vec3(0.299, 0.587, 0.114));\n    col = clamp(mix(vec3(grey), col, sat) * bright, 0.0, 1.0);\n\n    if (mode == 1) {\n        col = vec3(clamp(x * bright, 0.0, 1.0));\n    }\n    if (mode == 2) {\n        col = vec3(smoothstep(matte - soft - 0.002, matte + soft + 0.002, x));\n    }\n    if (invert == 1) {\n        col = 1.0 - col;\n    }\n    gl_FragColor = vec4(col, 1.0);\n}\n"
};
